ALTER TABLE children ADD COLUMN progress_storage_version INTEGER NOT NULL DEFAULT 1 CHECK(progress_storage_version IN(1,2));
ALTER TABLE children ADD COLUMN progress_navigation_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE children ADD COLUMN progress_navigation_revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE children ADD COLUMN progress_navigation_request TEXT;
ALTER TABLE children ADD COLUMN progress_navigation_hash TEXT;
ALTER TABLE children ADD COLUMN progress_summary_revision INTEGER NOT NULL DEFAULT 0;
CREATE TABLE progress_revisions (sequence INTEGER PRIMARY KEY AUTOINCREMENT,child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE,record_key TEXT NOT NULL,day INTEGER NOT NULL CHECK(day BETWEEN 1 AND 365),age TEXT NOT NULL CHECK(age IN('4-6','7-9','10-12','13-16')),protocol_version INTEGER NOT NULL CHECK(protocol_version BETWEEN 0 AND 999),revision INTEGER NOT NULL CHECK(revision>=0),request_id TEXT,request_hash TEXT,record_json TEXT NOT NULL CHECK(length(CAST(record_json AS BLOB))<=524288 OR (revision=0 AND source='legacy' AND request_id IS NULL AND length(CAST(record_json AS BLOB))<=1048576)),schema_json TEXT NOT NULL CHECK(length(CAST(schema_json AS BLOB))<=16384),step INTEGER NOT NULL CHECK(step BETWEEN 0 AND 3),viewed_steps INTEGER NOT NULL CHECK(viewed_steps BETWEEN 0 AND 15),completed INTEGER NOT NULL CHECK(completed IN(0,1)),completion_eligible INTEGER NOT NULL DEFAULT 0 CHECK(completion_eligible IN(0,1)),has_notes INTEGER NOT NULL CHECK(has_notes IN(0,1)),source TEXT NOT NULL CHECK(source IN('legacy','edit','import')),created_at INTEGER NOT NULL,UNIQUE(child_id,record_key,revision),UNIQUE(child_id,request_id));
CREATE TABLE progress_save_receipts (child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE,request_id TEXT NOT NULL,request_hash TEXT NOT NULL,record_key TEXT NOT NULL,applied_revision INTEGER NOT NULL,summary_json TEXT NOT NULL CHECK(length(CAST(summary_json AS BLOB))<=2048),created_at INTEGER NOT NULL,PRIMARY KEY(child_id,request_id));
CREATE INDEX progress_save_receipts_retention ON progress_save_receipts(child_id,created_at);
CREATE INDEX progress_revisions_history ON progress_revisions(child_id,record_key,revision);
CREATE INDEX progress_revisions_export ON progress_revisions(child_id,sequence);
CREATE TABLE progress_heads (child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE,record_key TEXT NOT NULL,day INTEGER NOT NULL,age TEXT NOT NULL,protocol_version INTEGER NOT NULL,revision INTEGER NOT NULL,sequence INTEGER NOT NULL REFERENCES progress_revisions(sequence) ON DELETE CASCADE,step INTEGER NOT NULL,viewed_steps INTEGER NOT NULL,completed INTEGER NOT NULL,completion_eligible INTEGER NOT NULL DEFAULT 0 CHECK(completion_eligible IN(0,1)),has_notes INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(child_id,record_key));
CREATE INDEX progress_heads_days ON progress_heads(child_id,day,age,protocol_version);
CREATE TRIGGER progress_revisions_immutable BEFORE UPDATE ON progress_revisions BEGIN SELECT RAISE(ABORT,'Progress revisions cannot be edited'); END;
CREATE TRIGGER progress_revision_head AFTER INSERT ON progress_revisions WHEN NEW.revision>0 BEGIN INSERT INTO progress_heads(child_id,record_key,day,age,protocol_version,revision,sequence,step,viewed_steps,completed,completion_eligible,has_notes,updated_at) VALUES(NEW.child_id,NEW.record_key,NEW.day,NEW.age,NEW.protocol_version,NEW.revision,NEW.sequence,NEW.step,NEW.viewed_steps,NEW.completed,NEW.completion_eligible,NEW.has_notes,NEW.created_at) ON CONFLICT(child_id,record_key) DO UPDATE SET revision=excluded.revision,sequence=excluded.sequence,step=excluded.step,viewed_steps=excluded.viewed_steps,completed=excluded.completed,completion_eligible=excluded.completion_eligible,has_notes=excluded.has_notes,updated_at=excluded.updated_at; UPDATE children SET progress_summary_revision=progress_summary_revision+1,updated_at=NEW.created_at WHERE id=NEW.child_id; END;
CREATE TRIGGER progress_legacy_state_frozen BEFORE UPDATE OF state_json ON children WHEN OLD.progress_storage_version=2 AND NEW.state_json!=OLD.state_json BEGIN SELECT RAISE(ABORT,'PROGRESS_UPGRADE_REQUIRED: legacy state is frozen'); END;
CREATE TRIGGER progress_storage_no_downgrade BEFORE UPDATE OF progress_storage_version ON children WHEN OLD.progress_storage_version=2 AND NEW.progress_storage_version!=2 BEGIN SELECT RAISE(ABORT,'PROGRESS_UPGRADE_REQUIRED: storage downgrade is unsafe'); END;
